"droit.1l":["Garde à vue et tes droits",[["Combien de temps dure une garde à vue en principe ?","24 heures, renouvelable une fois","Une semaine","Une heure","Sans limite"],["Refuser de répondre en garde à vue…","Est un droit et ne vaut pas aveu","Est un délit","Allonge automatiquement la garde à vue","Vaut aveu"],["Qu'est-ce que l'audition libre ?","Tu n'es pas retenu et peux partir à tout moment","Une garde à vue sans avocat","Un interrogatoire au tribunal","Une audience publique"],["Quel droit as-tu dès le début de la garde à vue ?","Être assisté d'un avocat","Rentrer chez toi le soir","Choisir ton enquêteur","Garder ton téléphone"]]],
