"droit.1n":["Logement et bail",[["Quelle est la durée du bail d'un logement vide loué par un particulier ?","Trois ans","Un an","Neuf mois","Six ans"],["Quel dépôt de garantie maximum pour un logement vide ?","Un mois de loyer hors charges","Trois mois","Six mois","Aucun"],["Depuis 2025, quels logements ne peuvent plus être loués ?","Ceux classés G au diagnostic énergétique","Ceux sans balcon","Ceux de moins de 20 m²","Ceux au rez-de-chaussée"],["Quelle garantie gratuite peut servir de garant pour les jeunes ?","Visale","Vigipirate","Visa","Vitale"]]],
