"droit.1q":["Contrats",[["Quelle condition faut-il pour qu'un contrat soit valable ?","Un consentement libre et éclairé","Un notaire","Un timbre fiscal","Un témoin"],["Un contrat doit-il toujours être écrit ?","Non, mais un écrit est conseillé pour le prouver","Oui, toujours","Seulement en ligne","Seulement s'il dépasse 100 €"],["Cocher « J'accepte les conditions générales » en ligne…","Forme un vrai contrat","N'a aucune valeur","Ne vaut que si on les a lues","Doit être confirmé par courrier"],["Que deviennent les clauses abusives entre un pro et un consommateur ?","Elles sont réputées non écrites","Elles s'appliquent quand même","Elles doublent le prix","Elles annulent tout le contrat"]]],
